import { EquirectangularReflectionMapping, type Texture } from "three";
import { HDRLoader } from "three/addons/loaders/HDRLoader.js";

/**
 * The viewer's default environment: Poly Haven's "Studio Small 08" HDRI (CC0, polyhaven.com/a/studio_small_08), its 1k version downscaled to 512×256
 * with a 2×2 box filter and stored as flat RGBE, base64 encoded. Its floor is a neutral light gray (0.9), blended in just below the horizon, as a
 * product photo's white sweep, so metal facing forward or down mirrors a light floor, as the light backgrounds the viewer sits on, not a dark one. A
 * module of its own, imported dynamically, so it's a chunk loaded only when the default environment is used
 */

export function loadStudio(): Promise<Texture> {
  return new HDRLoader()
    .loadAsync(`data:application/octet-stream;base64,${studio}`)
    .then((texture) => Object.assign(texture, { mapping: EquirectangularReflectionMapping }));
}

const studio =
  "";
